// 🧩 Función para limpiar el Markdown y dejar el texto plano y legible
function limpiarMarkdown(texto) {
  return texto
    // elimina símbolos comunes de Markdown
    .replace(/[*_#`>]/g, "")
    // elimina formato de enlaces [texto](url)
    .replace(/\[(.*?)\]\(.*?\)/g, "$1")
    // elimina separadores "---"
    .replace(/-{3,}/g, "")
    // colapsa saltos de línea múltiples
    .replace(/\n{2,}/g, "\n\n")
    // limpia espacios múltiples
    .replace(/\s{2,}/g, " ")
    // recorta espacios al inicio y final
    .trim();
}

// 🧩 Asegura que los saltos de línea sean reales para que Google Sheets los reconozca
function normalizarSaltos(texto) {
  return texto.replace(/\\n/g, "\n");
}

// 🧩 Extrae el contenido de cada sección (A, B, C, D)
function extraerSeccion(texto, letra) {
  const regex = new RegExp(`# ${letra}\\. (.*?)(?=\\n# [A-D]\\. |$)`, "s");
  const match = texto.match(regex);
  return match ? normalizarSaltos(limpiarMarkdown(match[0])) : "";
}

