});

// --- 1. Obtener los enlaces existentes de Google Sheets ---

// ¡CAMBIO AQUÍ! Leemos la propiedad correcta que ahora genera el nodo 'Aggregate'
const existingLinksArray = $('Aggregate').first().json['Link al vídeo tiktok'];

// Creamos un 'Set' con los enlaces existentes.
// Añadimos (existingLinksArray || []) para evitar un error si la hoja está vacía
const existingLinksSet = new Set(existingLinksArray || []);


// --- 2. Filtrar los nuevos vídeos de Apify ---

const uniqueNewVideos = [];

// Recorremos los ítems que llegan desde Apify
for (const item of items) {

  // Usamos la propiedad "webVideoUrl"
  const newVideoUrl = item.json.webVideoUrl; 

  // Comprobamos si el enlace existe y si NO está en el Set de enlaces existentes.
  if (newVideoUrl && !existingLinksSet.has(newVideoUrl)) {
    // Si es nuevo, lo añadimos a nuestra lista de resultados.
    uniqueNewVideos.push(item);
  }
}


// --- 3. Ordenar por 'playCount' y devolverlos TODOS ---

// Ordenamos de MAYOR a MENOR por 'playCount'
const sortedVideos = uniqueNewVideos.sort((a, b) => b.json.playCount - a.json.playCount);

// Devolvemos el array completo y ordenado.
return sortedVideos;
